var serialize = function(root) {
    const tokens = [];
    function visit(node) {
        if (node === null) {
            tokens.push('#');
            return;
        }
        tokens.push(String(node.val));
        visit(node.left);
        visit(node.right);
    }
    visit(root);
    return tokens.join(',');
};

var deserialize = function(data) {
    const values = data.split(',');
    let index = 0;
    function build() {
        const value = values[index++];
        if (value === '#') return null;
        const node = new TreeNode(parseInt(value, 10));
        node.left = build();
        node.right = build();
        return node;
    }
    return build();
};

